const accounts = Array.isArray($json) ? $json : [$json];
const account = accounts[0];
const postItems = $('Split Posts for Analytics').all();
const post = postItems[$itemIndex]?.json || postItems[0]?.json;
const platform = post?.plataforma;
const externalId = post?.external_id || `mock_${post?.id?.substring(0,8)}`;
const isMock = !account || account.is_mock;

let metrics;

if (isMock || !account?.access_token) {
  // Deterministic mock metrics seeded by post ID
  const seed = parseInt((post?.id || '').replace(/-/g,'').substring(0,8), 16) || 12345;
  const rng = (min, max, s) => min + Math.abs(Math.sin(s) * (max - min)) | 0;
  const imp = rng(2000, 45000, seed);
  const alcance = Math.floor(imp * (0.6 + Math.abs(Math.sin(seed * 2)) * 0.3));
  const eng = Math.floor(alcance * (0.02 + Math.abs(Math.sin(seed * 3)) * 0.08));
  const likes = Math.floor(eng * 0.6);
  const comentarios = Math.floor(eng * 0.15);
  const compartidos = Math.floor(eng * 0.1);
  const guardados = Math.floor(eng * 0.1);
  const clicks = Math.floor(alcance * (0.01 + Math.abs(Math.sin(seed * 4)) * 0.04));
  const seguidores = Math.floor(eng * 0.05);
  const engagement_rate = parseFloat((eng / Math.max(alcance, 1) * 100).toFixed(4));
  metrics = { impresiones: imp, alcance, engagement: eng, likes, comentarios, compartidos, guardados, clicks, seguidores_ganados: seguidores, engagement_rate };
} else {
  // Real API metrics would be fetched here in Phase 4
  // LinkedIn: GET https://api.linkedin.com/v2/organizationalEntityShareStatistics
  // Twitter: GET https://api.twitter.com/2/tweets/{id}?tweet.fields=public_metrics
  // Instagram/Facebook: GET https://graph.facebook.com/v18.0/{id}/insights
  metrics = { impresiones: 0, alcance: 0, engagement: 0, likes: 0, comentarios: 0, compartidos: 0, guardados: 0, clicks: 0, seguidores_ganados: 0, engagement_rate: 0 };
}

return [{ json: {
  post_id: post?.id,
  plataforma: platform,
  external_post_id: externalId,
  fecha_snapshot: new Date().toISOString(),
  ...metrics,
  metadata: { isMock, source: isMock ? 'n8n-mock' : 'api', collectedAt: new Date().toISOString() }
} }];
